SET search_path TO society_manager, public;
UPDATE m_support_faq SET question_hi='भुगतान कैसे करें?',answer_hi='कलेक्शन या माय बिलिंग खोलें, बिल चुनें और भुगतान पूरा करें।',question_mr='पेमेंट कसे करावे?',answer_mr='कलेक्शन किंवा माय बिलिंग उघडा, बिल निवडा आणि पेमेंट पूर्ण करा.',question_gu='ચુકવણી કેવી રીતે કરવી?',answer_gu='કલેક્શન અથવા માય બિલિંગ ખોલો, બિલ પસંદ કરો અને ચુકવણી પૂર્ણ કરો.',question_kn='ಪಾವತಿ ಹೇಗೆ ಮಾಡುವುದು?',answer_kn='ಕಲೆಕ್ಷನ್ ಅಥವಾ ಮೈ ಬಿಲ್ಲಿಂಗ್ ತೆರೆಯಿರಿ, ಬಿಲ್ ಆಯ್ಕೆಮಾಡಿ ಮತ್ತು ಪಾವತಿ ಪೂರ್ಣಗೊಳಿಸಿ.',question_ta='பணம் செலுத்துவது எப்படி?',answer_ta='கலெக்ஷன் அல்லது மை பில்லிங் திறந்து, பில்லைத் தேர்வு செய்து பணம் செலுத்துங்கள்.' WHERE society_id IS NULL AND faq_code='PAYMENT';
UPDATE m_support_faq SET question_hi='आगंतुक कैसे जोड़ें?',answer_hi='विज़िटर मैनेजमेंट में प्री-अप्रूव्ड विज़िटर आमंत्रण बनाएं।',question_mr='अभ्यागत कसा जोडावा?',answer_mr='व्हिजिटर मॅनेजमेंटमध्ये पूर्व-मंजूर अभ्यागत आमंत्रण तयार करा.',question_gu='મુલાકાતી કેવી રીતે ઉમેરવો?',answer_gu='વિઝિટર મેનેજમેન્ટમાં પૂર્વ-મંજૂર મુલાકાતી આમંત્રણ બનાવો.',question_kn='ಭೇಟಿದಾರರನ್ನು ಹೇಗೆ ಸೇರಿಸುವುದು?',answer_kn='ವಿಸಿಟರ್ ಮ್ಯಾನೇಜ್‌ಮೆಂಟ್‌ನಲ್ಲಿ ಪೂರ್ವ-ಅನುಮೋದಿತ ಭೇಟಿ ಆಹ್ವಾನ ರಚಿಸಿ.',question_ta='பார்வையாளரை எப்படி சேர்ப்பது?',answer_ta='விசிட்டர் மேனேஜ்மெண்டில் முன் அங்கீகரிக்கப்பட்ட பார்வையாளர் அழைப்பை உருவாக்குங்கள்.' WHERE society_id IS NULL AND faq_code='VISITOR';
UPDATE m_support_faq SET question_hi='शिकायत कैसे दर्ज करें?',answer_hi='शिकायतें या ग्राहक पोर्टल खोलें और समस्या का विवरण सबमिट करें।',question_mr='तक्रार कशी नोंदवावी?',answer_mr='तक्रारी किंवा ग्राहक पोर्टल उघडा आणि समस्येचे तपशील सबमिट करा.',question_gu='ફરિયાદ કેવી રીતે નોંધાવવી?',answer_gu='ફરિયાદો અથવા ગ્રાહક પોર્ટલ ખોલો અને સમસ્યાની વિગતો સબમિટ કરો.',question_kn='ದೂರು ಹೇಗೆ ಸಲ್ಲಿಸುವುದು?',answer_kn='ದೂರುಗಳು ಅಥವಾ ಗ್ರಾಹಕ ಪೋರ್ಟಲ್ ತೆರೆಯಿರಿ ಮತ್ತು ಸಮಸ್ಯೆಯ ವಿವರಗಳನ್ನು ಸಲ್ಲಿಸಿ.',question_ta='புகாரை எப்படி பதிவு செய்வது?',answer_ta='புகார்கள் அல்லது வாடிக்கையாளர் போர்டலைத் திறந்து பிரச்சனை விவரங்களை சமர்ப்பிக்கவும்.' WHERE society_id IS NULL AND faq_code='COMPLAINT';
UPDATE m_support_faq SET question_hi='बकाया कैसे देखें?',answer_hi='माय बिलिंग या ग्राहक 360 खोलें।',question_mr='बाकी रक्कम कशी पाहावी?',answer_mr='माय बिलिंग किंवा ग्राहक 360 उघडा.',question_gu='બાકી રકમ કેવી રીતે જોવી?',answer_gu='માય બિલિંગ અથવા ગ્રાહક 360 ખોલો.',question_kn='ಬಾಕಿ ಮೊತ್ತವನ್ನು ಹೇಗೆ ನೋಡುವುದು?',answer_kn='ಮೈ ಬಿಲ್ಲಿಂಗ್ ಅಥವಾ ಗ್ರಾಹಕ 360 ತೆರೆಯಿರಿ.',question_ta='நிலுவைத் தொகையை எப்படி பார்ப்பது?',answer_ta='மை பில்லிங் அல்லது வாடிக்கையாளர் 360 திறக்கவும்.' WHERE society_id IS NULL AND faq_code='DUES';
UPDATE m_support_faq SET question_hi='रसीद कैसे डाउनलोड करें?',answer_hi='कलेक्शन या भुगतान इतिहास खोलें और भुगतान की रसीद खोलें।',question_mr='पावती कशी डाउनलोड करावी?',answer_mr='कलेक्शन किंवा पेमेंट हिस्टरी उघडा आणि पेमेंटची पावती उघडा.',question_gu='રસીદ કેવી રીતે ડાઉનલોડ કરવી?',answer_gu='કલેક્શન અથવા પેમેન્ટ હિસ્ટરી ખોલો અને ચુકવણીની રસીદ ખોલો.',question_kn='ರಸೀದಿಯನ್ನು ಹೇಗೆ ಡೌನ್‌ಲೋಡ್ ಮಾಡುವುದು?',answer_kn='ಕಲೆಕ್ಷನ್ ಅಥವಾ ಪಾವತಿ ಇತಿಹಾಸ ತೆರೆಯಿರಿ ಮತ್ತು ಪಾವತಿ ರಸೀದಿ ತೆರೆಯಿರಿ.',question_ta='ரசீதை எப்படி பதிவிறக்குவது?',answer_ta='கலெக்ஷன் அல்லது கட்டண வரலாற்றைத் திறந்து கட்டண ரசீதைத் திறக்கவும்.' WHERE society_id IS NULL AND faq_code='RECEIPT';
UPDATE m_support_faq SET question_hi='ग्राहक कैसे जोड़ें?',answer_hi='अधिकृत स्टाफ CRM या निवासी मॉड्यूल में ग्राहक जोड़ सकता है।',question_mr='ग्राहक कसा जोडावा?',answer_mr='अधिकृत कर्मचारी CRM किंवा रहिवासी मॉड्यूलमध्ये ग्राहक जोडू शकतो.',question_gu='ગ્રાહક કેવી રીતે ઉમેરવો?',answer_gu='અધિકૃત સ્ટાફ CRM અથવા રહેવાસી મોડ્યુલમાં ગ્રાહક ઉમેરી શકે છે.',question_kn='ಗ್ರಾಹಕರನ್ನು ಹೇಗೆ ಸೇರಿಸುವುದು?',answer_kn='ಅಧಿಕೃತ ಸಿಬ್ಬಂದಿ CRM ಅಥವಾ ನಿವಾಸಿಗಳಲ್ಲಿ ಗ್ರಾಹಕರನ್ನು ಸೇರಿಸಬಹುದು.',question_ta='வாடிக்கையாளரை எப்படி சேர்ப்பது?',answer_ta='அங்கீகரிக்கப்பட்ட பணியாளர்கள் CRM அல்லது குடியிருப்பாளர்கள் பகுதியில் வாடிக்கையாளரை சேர்க்கலாம்.' WHERE society_id IS NULL AND faq_code='CUSTOMER';